export function voiceEngineInfo(engine: VoiceEngineId | undefined): VoiceEngineInfo | undefined {
  return VOICE_ENGINES.find((e) => e.id === engine);
}

/** The engine whose packs include `packId`. */
export function voiceEngineOfPack(packId: string): VoiceEngineInfo | undefined {
  return VOICE_ENGINES.find((e) => e.packIds.includes(packId));
}
